-- Справочные статьи о платформе (platform_articles.json) в knowledge_base для каждого психолога.
-- Эмбеддинги считаются потом: ./reindex_embeddings.sh run. Повторный запуск не дублирует.
begin;
insert into public.knowledge_base (psychologist_id, title, content, source_type, topic)
select p.id, $a0$Часовой пояс: где меняется и на что влияет$a0$, $a0$Часовой пояс психолога задаётся в разделе «Настройки» → «Публичная запись» (не на главной странице настроек, а на отдельной вкладке для записи клиентов). По умолчанию установлен часовой пояс Europe/Moscow (Москва). Доступны 16 поясов, актуальных для России и СНГ: Калининград, Москва, Самара, Екатеринбург, Омск, Красноярск, Иркутск, Якутск, Владивосток, Магадан, Камчатка, а также Алматы, Ташкент, Тбилиси, Ереван, Минск.

Часовой пояс влияет на всё, что связано со временем в кабинете: как трактуются заданные рабочие часы, какие слоты видит клиент на странице публичной записи, как отображаются даты и время всех сессий в календаре и списке, что ассистент считает «сегодня», «завтра» и «через час», и какая дата стоит в шапке PDF-протокола сессии.

Если часовой пояс браузера психолога отличается от сохранённого в настройках, интерфейс показывает предупреждение об этом прямо на странице «Публичная запись» — стоит свериться и поправить, если пояс указан неверно.$a0$, 'manual', 'platform' from public.psychologists p
where p.deleted_at is null and not exists (select 1 from public.knowledge_base k where k.psychologist_id = p.id and k.topic = 'platform' and k.title = $a0$Часовой пояс: где меняется и на что влияет$a0$);
insert into public.knowledge_base (psychologist_id, title, content, source_type, topic)
select p.id, $a1$Рабочие часы и параметры записи (буфер, минимальное уведомление)$a1$, $a1$Рабочие часы и параметры онлайн-записи настраиваются там же, где часовой пояс — «Настройки» → «Публичная запись». Рабочие часы задаются отдельно на каждый день недели: указывается интервал (например, 10:00–19:00) или день помечается как выходной. По умолчанию рабочими считаются будни 10:00–19:00, суббота и воскресенье — выходные.

Дополнительно настраиваются: длительность сессии (30, 50, 60 или 90 минут, по умолчанию 50), буфер между сессиями (0, 10, 15 или 30 минут — пауза, которая не даёт двум сессиям идти впритык, по умолчанию 10 минут), минимальное время до записи (1, 2, 4 или 24 часа — за сколько часов до начала клиент ещё может забронировать слот, по умолчанию 2 часа) и горизонт записи (7, 14, 30 или 60 дней вперёд, по умолчанию 30 дней).

Эти настройки определяют, какие именно слоты ассистент предлагает клиентам психолога и какие слоты видны на странице публичной записи — оба места используют одну и ту же логику расчёта.$a1$, 'manual', 'platform' from public.psychologists p
where p.deleted_at is null and not exists (select 1 from public.knowledge_base k where k.psychologist_id = p.id and k.topic = 'platform' and k.title = $a1$Рабочие часы и параметры записи (буфер, минимальное уведомление)$a1$);
insert into public.knowledge_base (psychologist_id, title, content, source_type, topic)
select p.id, $a2$Публичная запись: как клиент бронирует сессию по ссылке$a2$, $a2$На странице «Настройки» → «Публичная запись» есть тумблер, включающий приём записи от клиентов, и персональная ссылка вида tolk.pro/book/имя-психолога, которую можно скопировать и отправить клиенту. Ссылка формируется автоматически на основе имени психолога при первом сохранении настроек — вручную задать свой адрес нельзя.

Со стороны клиента процесс выглядит так: он переходит по ссылке без регистрации, видит имя и специализацию психолога, выбирает дату по неделям и удобное время из реально свободных слотов, затем указывает своё имя и Telegram и подтверждает запись. После этого он видит сообщение с датой и временем сессии по часовому поясу психолога (это явно подписано).

Важный нюанс: созданная таким образом сессия получает статус «ожидает подтверждения», а не сразу становится подтверждённой. Текст, который видит клиент после бронирования, зависит от того, подключён ли у психолога Telegram-бот: если да — клиенту напишут о подтверждении в Telegram, если нет — психолог должен связаться с клиентом сам.$a2$, 'manual', 'platform' from public.psychologists p
where p.deleted_at is null and not exists (select 1 from public.knowledge_base k where k.psychologist_id = p.id and k.topic = 'platform' and k.title = $a2$Публичная запись: как клиент бронирует сессию по ссылке$a2$);
insert into public.knowledge_base (psychologist_id, title, content, source_type, topic)
select p.id, $a3$Уведомления: что работает сейчас, а что в разработке$a3$, $a3$В разделе «Настройки» есть вкладка «Уведомления» со списком: напоминания о сессиях за 15 минут, уведомления о новых сообщениях от клиентов, отметки о выполнении домашних заданий и новости продукта. Важно понимать честно: на сентябрь 2026 года все эти пункты помечены в интерфейсе как «Скоро» — отдельная настройка push- и email-уведомлений ещё не подключена, и менять здесь пока нечего.

Единственный реально работающий канал получения сообщений от клиента — это встроенный чат в карточке клиента, куда попадают сообщения из подключённых мессенджеров (Telegram, ВКонтакте), если психолог их настроил. Если психологу нужно узнавать о новом сообщении клиента сразу, а не заходя в кабинет, — на сегодня для этого стоит держать открытым сам Telegram или ВКонтакте, куда пишет клиент.$a3$, 'manual', 'platform' from public.psychologists p
where p.deleted_at is null and not exists (select 1 from public.knowledge_base k where k.psychologist_id = p.id and k.topic = 'platform' and k.title = $a3$Уведомления: что работает сейчас, а что в разработке$a3$);
insert into public.knowledge_base (psychologist_id, title, content, source_type, topic)
select p.id, $a4$Тарифы и лимит запросов ассистенту$a4$, $a4$У платформы четыре тарифных названия с разным месячным лимитом запросов к ассистенту: «Бета» — 200 запросов, «Практика» — 60, «Профессионал» — 200, «Эксперт» — 600. Текущий расход виден в сайдбаре кабинета и в разделе «Настройки» → «Тариф и оплата».

Лимит расходуется неравномерно в зависимости от типа запроса: обычный вопрос ассистенту стоит 1 запрос из лимита, срез за период по клиенту — 3 запроса (это более тяжёлая операция), поиск по базе знаний — 1 запрос. Генерация протокола сессии (SOAP) лимит НЕ расходует вообще — она оплачивается платформой отдельно и не ограничена тарифом.

Лимит обновляется раз в месяц. Если запросы заканчиваются, ассистент перестаёт отвечать до начала следующего месяца или до докупки дополнительного пакета. Важная честная оговорка на время беты: кнопка докупки пакетов запросов в интерфейсе сейчас не подключена к реальной оплате — раздел тарифов и биллинга ещё в разработке, и текущий тариф каждому психологу назначается вручную.$a4$, 'manual', 'platform' from public.psychologists p
where p.deleted_at is null and not exists (select 1 from public.knowledge_base k where k.psychologist_id = p.id and k.topic = 'platform' and k.title = $a4$Тарифы и лимит запросов ассистенту$a4$);
insert into public.knowledge_base (psychologist_id, title, content, source_type, topic)
select p.id, $a5$Как подключить Telegram-бота для переписки с клиентами$a5$, $a5$Подключить Telegram-бота можно в разделе «Настройки» → «Интеграции». Порядок действий: создать своего бота через официальный аккаунт @BotFather в Telegram командой /newbot, получить токен бота, вставить этот токен в форму на странице интеграций в кабинете ТОЛК. Система сама проверит токен и подключит бота.

После подключения психолог отправляет клиенту персональную ссылку на бота (её видно в разделе интеграций) — когда клиент переходит по ней и нажимает «Старт», его переписка привязывается к карточке этого клиента, и все дальнейшие текстовые сообщения клиента появляются во внутреннем чате кабинета. Обратите внимание: бот пока умеет работать только с текстом — фотографии, голосовые сообщения и файлы, присланные клиентом, в чате не отображаются как есть.

Таким же образом (через тот же раздел «Интеграции») подключается сообщество ВКонтакте — принцип работы аналогичный.$a5$, 'manual', 'platform' from public.psychologists p
where p.deleted_at is null and not exists (select 1 from public.knowledge_base k where k.psychologist_id = p.id and k.topic = 'platform' and k.title = $a5$Как подключить Telegram-бота для переписки с клиентами$a5$);
insert into public.knowledge_base (psychologist_id, title, content, source_type, topic)
select p.id, $a6$Шаблоны протоколов сессии: где создать и как они применяются$a6$, $a6$Шаблоны протоколов находятся в разделе «База знаний» на вкладке «Шаблоны протоколов» (раньше это была отдельная страница, сейчас перенесена в базу знаний). Там можно создать свой шаблон — задать структуру и акценты, на которые должен ориентироваться будущий протокол.

При генерации протокола сессии (кнопка «Сгенерировать протокол» в карточке сессии) психолог может выбрать один из своих шаблонов — тогда ассистент учтёт структуру и акценты этого шаблона при распределении информации по стандартным блокам протокола (жалоба и запрос, наблюдения, гипотеза, план). Сам протокол всегда сохраняется в одном и том же формате из четырёх блоков — шаблон влияет на содержание, а не на формат хранения. Если шаблон не выбран, используется формат по умолчанию.

Выбранный шаблон также запоминается и учитывается при выгрузке протокола в PDF.$a6$, 'manual', 'platform' from public.psychologists p
where p.deleted_at is null and not exists (select 1 from public.knowledge_base k where k.psychologist_id = p.id and k.topic = 'platform' and k.title = $a6$Шаблоны протоколов сессии: где создать и как они применяются$a6$);
insert into public.knowledge_base (psychologist_id, title, content, source_type, topic)
select p.id, $a7$Как отправить резюме сессии клиенту — и честно о том, чего пока нет$a7$, $a7$На странице протокола сессии есть возможность подготовить короткое резюме сессии для клиента и сохранить его в системе. Важно понимать точно, как это работает на сентябрь 2026 года: сохранение резюме в кабинете — это реальная и рабочая функция, но автоматической отправки этого текста клиенту в Telegram, ВКонтакте или другой мессенджер платформа пока не выполняет.

После сохранения резюме психологу нужно скопировать текст самому и переслать клиенту вручную — например, через тот же чат в карточке клиента или напрямую в мессенджере. Если ассистент отвечает, что резюме «уже отправлено клиенту в Telegram» — это неточность, и на самом деле нужно отправить текст самостоятельно.$a7$, 'manual', 'platform' from public.psychologists p
where p.deleted_at is null and not exists (select 1 from public.knowledge_base k where k.psychologist_id = p.id and k.topic = 'platform' and k.title = $a7$Как отправить резюме сессии клиенту — и честно о том, чего пока нет$a7$);
insert into public.knowledge_base (psychologist_id, title, content, source_type, topic)
select p.id, $a8$Экспорт транскриптов сессий$a8$, $a8$Транскрипт (текстовая расшифровка разговора) отдельной сессии можно скачать кнопкой «Скачать транскрипт» на странице протокола этой сессии — файл придёт в формате обычного текстового документа. Кнопка активна только если расшифровка уже готова; если запись сессии ещё обрабатывается, скачивание будет недоступно.

Если нужно выгрузить сразу все транскрипты по одному клиенту — это делается кнопкой «Выгрузить все транскрипты» в карточке клиента: она соберёт расшифровки всех сессий этого клиента в один файл.

Важная деталь про содержание: перед сохранением каждый транскрипт автоматически анонимизируется — из текста убираются имена третьих лиц, конкретные даты и места, упомянутые в разговоре, что дополнительно снижает риск при хранении и передаче таких файлов.$a8$, 'manual', 'platform' from public.psychologists p
where p.deleted_at is null and not exists (select 1 from public.knowledge_base k where k.psychologist_id = p.id and k.topic = 'platform' and k.title = $a8$Экспорт транскриптов сессий$a8$);
insert into public.knowledge_base (psychologist_id, title, content, source_type, topic)
select p.id, $a9$Скачивание протокола сессии в PDF$a9$, $a9$Готовый протокол сессии можно выгрузить в PDF прямо со страницы протокола — файл формируется настоящим PDF-документом (не имитацией), в шапке которого стоит корректная дата сессии с учётом часового пояса психолога. Если при создании протокола был выбран шаблон из базы знаний, его название тоже попадёт в шапку PDF.

Выгрузить PDF можно только после того, как протокол сохранён — если протокол ещё не создан или не заполнен, система сообщит, что сначала нужно завершить работу с протоколом на странице сессии.$a9$, 'manual', 'platform' from public.psychologists p
where p.deleted_at is null and not exists (select 1 from public.knowledge_base k where k.psychologist_id = p.id and k.topic = 'platform' and k.title = $a9$Скачивание протокола сессии в PDF$a9$);
insert into public.knowledge_base (psychologist_id, title, content, source_type, topic)
select p.id, $a10$Экспорт своих данных из аккаунта$a10$, $a10$В разделе «Настройки» → «Конфиденциальность» есть кнопка «Экспортировать мои данные». На сентябрь 2026 года стоит понимать честно: эта функция ещё не подключена технически — по нажатию появляется уведомление о том, что экспорт «будет отправлен на почту», но фактической выгрузки данных и письма не происходит. Отдельного экспорта списка клиентов в файл (например, в Excel) в системе тоже пока нет.

Если психологу прямо сейчас нужно выгрузить свои данные — доступны точечные варианты: скачивание протокола конкретной сессии в PDF и скачивание транскриптов (по одной сессии или все транскрипты клиента списком) — это описано в других разделах базы знаний. Полный экспорт всех данных аккаунта — в разработке, и с этим вопросом стоит обращаться в поддержку.$a10$, 'manual', 'platform' from public.psychologists p
where p.deleted_at is null and not exists (select 1 from public.knowledge_base k where k.psychologist_id = p.id and k.topic = 'platform' and k.title = $a10$Экспорт своих данных из аккаунта$a10$);
insert into public.knowledge_base (psychologist_id, title, content, source_type, topic)
select p.id, $a11$Безопасность и конфиденциальность данных клиентов$a11$, $a11$В разделе «Настройки» → «Конфиденциальность» указано, что данные клиентов хранятся на серверах, физически расположенных в России, платформа соответствует требованиям 152-ФЗ «О персональных данных», а передача и хранение данных происходят в зашифрованном виде.

Помимо этих заявленных мер, в самой системе реализована технически проверяемая защита на уровне базы данных: доступ к записям (клиенты, сессии, настройки записи и другие данные психолога) разграничен так, что каждый психолог видит и может изменять только свои собственные данные — это отдельный, независимый от паролей и сессий, уровень защиты на стороне базы данных. Транскрипты разговоров с клиентами дополнительно анонимизируются перед сохранением — имена третьих лиц, точные даты и места, упомянутые в разговоре, автоматически убираются из текста.

При необходимости точных формулировок для клиента или подрядчика (например, договора об обработке персональных данных) правильнее опираться на официальный текст политики конфиденциальности платформы, а не пересказывать её своими словами — за подробностями стоит обращаться в поддержку.$a11$, 'manual', 'platform' from public.psychologists p
where p.deleted_at is null and not exists (select 1 from public.knowledge_base k where k.psychologist_id = p.id and k.topic = 'platform' and k.title = $a11$Безопасность и конфиденциальность данных клиентов$a11$);
insert into public.knowledge_base (psychologist_id, title, content, source_type, topic)
select p.id, $a12$Что такое «срез за период» по клиенту$a12$, $a12$Срез за период — это функция ассистента, которая анализирует все сессии психолога с конкретным клиентом за выбранный промежуток времени (например, за месяц или с начала работы) и собирает из них общую картину: основные темы, изменения в состоянии клиента, повторяющиеся паттерны. Это не техническая настройка платформы, а один из инструментов самого ассистента — попросить его можно прямо в чате, например: «Сделай срез по Марине за последний месяц».

Эта операция тяжелее обычного вопроса и расходует сразу 3 запроса из месячного лимита ассистента (вместо 1 за обычный вопрос), потому что ассистенту нужно проанализировать сразу несколько сессий, а не ответить на один короткий вопрос. Результат среза сохраняется в истории и может использоваться как контекст для следующих протоколов этого клиента.$a12$, 'manual', 'platform' from public.psychologists p
where p.deleted_at is null and not exists (select 1 from public.knowledge_base k where k.psychologist_id = p.id and k.topic = 'platform' and k.title = $a12$Что такое «срез за период» по клиенту$a12$);
insert into public.knowledge_base (psychologist_id, title, content, source_type, topic)
select p.id, $a13$Как загрузить сессию вручную: текст/транскрипт, если встреча была вне платформы$a13$, $a13$Если сессия прошла не через видеозвонок платформы (например, в Zoom, по телефону или очно), а также если автоматическая расшифровка не удалась, текст сессии можно добавить вручную. Откройте страницу протокола нужной сессии (Сессии → выбрать сессию → протокол) и нажмите кнопку «Загрузить транскрипт».

В открывшемся окне есть два способа: загрузить обычный текстовый файл .txt или вставить текст расшифровки прямо в поле. После сохранения транскрипт попадает в историю клиента так же, как автоматический: по нему можно сгенерировать протокол сессии (SOAP), а ассистент сможет искать по нему и отвечать на вопросы об этой сессии.

Важно: загружается именно текст. Загрузка аудио- или видеофайла на платформе пока не поддерживается — если у вас есть только запись, её нужно сначала расшифровать сторонним сервисом, а затем загрузить получившийся текст. Сессии, проведённые через видеозвонок платформы, записываются и расшифровываются автоматически, их загружать не нужно.$a13$, 'manual', 'platform' from public.psychologists p
where p.deleted_at is null and not exists (select 1 from public.knowledge_base k where k.psychologist_id = p.id and k.topic = 'platform' and k.title = $a13$Как загрузить сессию вручную: текст/транскрипт, если встреча была вне платформы$a13$);
select 'статей о платформе: ' || count(*) from public.knowledge_base where topic = 'platform';
commit;
